# One-time setup for the VERIQ Scanner Flutter project (Windows PowerShell).
#
#   cd mobile
#   powershell -ExecutionPolicy Bypass -File tool\setup.ps1
#
# The repository contains the app code, tests and the Android files we customise
# (AndroidManifest.xml, network security config, icons, splash, MainActivity). The Gradle
# build files and wrapper are generated by *your* Flutter version with `flutter create`,
# which never overwrites existing files, and are then patched:
#   - applicationId / namespace -> com.veriq.scanner
#   - minSdk -> 23
$ErrorActionPreference = 'Stop'
Set-Location -Path (Join-Path $PSScriptRoot '..')

if (-not (Get-Command flutter -ErrorAction SilentlyContinue)) {
  throw 'flutter is not on PATH. Install Flutter (https://docs.flutter.dev/get-started/install/windows) and reopen the terminal.'
}

Write-Host '1/4 Generating Android project files (existing files are kept)...'
flutter create --org com.veriq --project-name veriq_scanner --platforms android --no-pub .
if ($LASTEXITCODE -ne 0) { throw 'flutter create failed' }

Write-Host '2/4 Applying package name com.veriq.scanner and minSdk 23...'
$gradle = @('android/app/build.gradle.kts', 'android/app/build.gradle') | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $gradle) { throw 'android/app/build.gradle(.kts) not found after flutter create' }
$text = [IO.File]::ReadAllText((Resolve-Path $gradle))
$text = $text -replace 'com\.veriq\.veriq_scanner', 'com.veriq.scanner'
if ($text -match 'minSdk(Version)?\s*=?\s*flutter\.minSdkVersion') {
  $text = $text -replace 'minSdk(Version)?\s*=?\s*flutter\.minSdkVersion', 'minSdk = 23'
} elseif ($text -notmatch 'minSdk\s*=\s*23') {
  Write-Warning "Could not find the minSdk line in $gradle - set minSdk = 23 manually."
}
[IO.File]::WriteAllText((Resolve-Path $gradle), $text, (New-Object Text.UTF8Encoding $false))
Write-Host "   patched $gradle"

# flutter create puts its MainActivity under the derived package; ours lives in com/veriq/scanner.
foreach ($dir in @('android/app/src/main/kotlin/com/veriq/veriq_scanner', 'android/app/src/main/java/com/veriq/veriq_scanner')) {
  if (Test-Path $dir) { Remove-Item -Recurse -Force $dir; Write-Host "   removed generated $dir" }
}

Write-Host '3/4 Fetching packages...'
flutter pub get
if ($LASTEXITCODE -ne 0) { throw 'flutter pub get failed' }

Write-Host '4/4 Static analysis and tests...'
flutter analyze
flutter test

Write-Host ''
Write-Host 'Done. Run on the connected phone with:'
Write-Host '  flutter run --dart-define=SERVER_URL=http://<PC-LAN-IP>:4000 --dart-define=APP_KEY=<flutter-app key>'
